function renderRichText(target, text) {
  target.replaceChildren();
  const inline=(el,value)=>{
    for(const part of value.split(/(\*\*[^*\n]+\*\*|`[^`\n]+`)/g)){
      if(part.startsWith('**')&&part.endsWith('**')){const b=document.createElement('strong');b.textContent=part.slice(2,-2);el.append(b);}
      else if(part.startsWith('`')&&part.endsWith('`')){const c=document.createElement('code');c.textContent=part.slice(1,-1);el.append(c);}
      else el.append(document.createTextNode(part));
    }
  };
  const prose=value=>{
    for(const paragraph of value.split(/\n\s*\n/)){
      if(!paragraph.trim())continue;
      const heading=paragraph.match(/^#{1,4}\s+([^\n]+)$/);
      const el=document.createElement(heading?'h3':'p');inline(el,heading?heading[1]:paragraph);target.append(el);
    }
  };
  const pattern=/```([\w+-]*)\n([\s\S]*?)(?:```|$)/g;
  let last=0;
  for(const match of text.matchAll(pattern)){
    prose(text.slice(last,match.index));last=match.index+match[0].length;
    const language=(match[1]||'text').toLowerCase(),value=match[2].replace(/\n$/,'');
    const shell=document.createElement('section');shell.className='code-shell';
    const bar=document.createElement('div');bar.className='code-bar';
    const label=document.createElement('span');label.className='code-language';label.textContent=language==='js'?'JavaScript':language==='python'?'Python':language.toUpperCase();
    const actions=document.createElement('div');actions.className='code-actions';
    const pre=document.createElement('pre'),code=document.createElement('code');code.textContent=value;
    if(window.hljs&&hljs.getLanguage(language))code.className='language-'+language;
    pre.append(code);
    const button=(icon,label,fn)=>{const b=document.createElement('button');b.type='button';b.innerHTML=UI_ICONS[icon];b.title=label;b.setAttribute('aria-label',label);b.addEventListener('click',fn);actions.append(b);return b;};
    button('file-code','Tải tệp code',()=>downloadText(value,'ChatAI-code.'+({python:'py',javascript:'js',js:'js',html:'html',css:'css',json:'json',sql:'sql'}[language]||'txt')));
    button('maximize-2','Xem code lớn',()=>openCodePanel(value,language));
    const copy=button('copy','Sao chép code',()=>copyValue(value,copy));
    bar.append(label,actions);shell.append(bar,pre);target.append(shell);
    if(window.hljs)hljs.highlightElement(code);
  }
  prose(text.slice(last));
  if(window.renderMathInElement){
    renderMathInElement(target,{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false}],throwOnError:false,trust:false,strict:'ignore',maxExpand:1000});
    target.querySelectorAll('.katex-display').forEach(math=>{
      const raw=math.querySelector('annotation[encoding="application/x-tex"]')?.textContent||'';
      const shell=document.createElement('div');shell.className='math-shell';
      math.replaceWith(shell);shell.append(math);
      const copy=document.createElement('button');copy.type='button';copy.className='math-copy';copy.innerHTML=UI_ICONS.copy+'<span>LaTeX</span>';copy.title='Sao chép công thức LaTeX';copy.addEventListener('click',()=>copyValue(raw,copy));shell.append(copy);
    });
  }
}


function manageConversation(index) {
  if (streaming) return toast("Hãy dừng hoặc đợi AI trả lời xong trước khi quản lý hội thoại.");
  closeSidebar();
  editingConversation = index;
  delete document.querySelector("#archiveChat").dataset.confirm;
  document.querySelector("#conversationName").value = conversations[index].title;
  document.querySelector("#conversationError").hidden = true;
  document.querySelector("#archiveChat").textContent = "Ẩn hội thoại khỏi danh sách";
  openOverlay("#conversationOverlay");
}
document.querySelector("#conversationForm").addEventListener("submit",async event => {
  event.preventDefault();
  const item=conversations[editingConversation]; if (!item) return;
  const title=document.querySelector("#conversationName").value.trim(); if(!title)return;
  const button=event.currentTarget.querySelector("[type=submit]");button.disabled=true;
  try {
    if(LIVE&&session&&item.id)await api("/api/conversations/rename",{...credentials(),conversation_id:item.id,title});
    item.title=title;renderConversations(els.search.value);closeOverlay("#conversationOverlay");toast("Đã đổi tên hội thoại.");
  } catch(error) { const el=document.querySelector("#conversationError");el.textContent=error.message;el.hidden=false; }
  finally { button.disabled=false; }
});
document.querySelector("#conversationCancel").addEventListener("click",()=>closeOverlay("#conversationOverlay"));
document.querySelector("#archiveChat").addEventListener("click",async event=>{
  const item=conversations[editingConversation];if(!item)return;
  const button=event.currentTarget;
  if(button.dataset.confirm!==String(editingConversation)){button.dataset.confirm=String(editingConversation);button.textContent="Bấm lần nữa để xác nhận ẩn";return;}
  button.disabled=true;
  try{
    if(LIVE&&session&&item.id)await api("/api/conversations/delete",{...credentials(),conversation_id:item.id,confirm:true});
    const active=currentConversation();conversations.splice(editingConversation,1);activeId=conversations.indexOf(active);
    if(activeId<0)startNewChat();else renderConversations(els.search.value);
    closeOverlay("#conversationOverlay");toast("Đã ẩn hội thoại.");
  }catch(error){toast(error.message);}finally{button.disabled=false;delete button.dataset.confirm;}
});
document.querySelector("#exportChat").addEventListener("click",async()=>{
  const convo=currentConversation();
  if(!convo?.messages.length)return toast("Chọn một hội thoại để xuất nội dung.");
  if(streaming)return toast("Đợi câu trả lời hoàn tất hoặc bấm Dừng trước khi xuất.");
  const text=`# ${convo.title}\n\n`+convo.messages.map(m=>`## ${m.role==='user'?'Bạn':'ChatAI'}\n\n${m.text}`).join("\n\n---\n\n");
  const url=URL.createObjectURL(new Blob([text],{type:"text/markdown;charset=utf-8"}));
  const link=document.createElement("a");link.href=url;link.download="ChatAI-"+new Date().toISOString().slice(0,10)+".md";link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  toast("Đã xuất hội thoại dạng Markdown.");
});
