async function copyValue(value,button){
  try{
    if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);
    else {const input=document.createElement('textarea');input.value=value;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();if(!document.execCommand('copy'))throw Error('copy');input.remove();}
    if(button){const previous=button.innerHTML;button.innerHTML=UI_ICONS.check;setTimeout(()=>{if(button.isConnected)button.innerHTML=previous;},1400);}
    toast('Đã sao chép.');
  }catch{toast('Chọn nội dung và dùng Ctrl + C hoặc nhấn giữ để sao chép.');}
}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openCodePanel(text,language){
 let overlay=document.querySelector('#codeOverlay');
 if(!overlay){overlay=document.createElement('div');overlay.id='codeOverlay';overlay.className='overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Xem code');overlay.innerHTML='<div class="code-view"><div class="code-view-bar"><strong></strong><button type="button" aria-label="Đóng code">'+UI_ICONS.x+'</button></div><pre><code></code></pre></div>';document.body.append(overlay);overlay.querySelector('button').onclick=()=>{overlay.hidden=true;};overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.hidden=true;});}
 overlay.querySelector('strong').textContent=language;const code=overlay.querySelector('code');code.textContent=text;code.className='language-'+language;delete code.dataset.highlighted;if(window.hljs)hljs.highlightElement(code);overlay.hidden=false;overlay.querySelector('button').focus();
}
document.querySelector('#pasteButton').innerHTML=UI_ICONS['clipboard-paste'];
document.querySelector('#pasteButton').addEventListener('click',async()=>{try{const text=await navigator.clipboard.readText();els.input.setRangeText(text,els.input.selectionStart,els.input.selectionEnd,'end');els.input.dispatchEvent(new Event('input'));els.input.focus();}catch{toast('Bấm vào ô nhập rồi dùng Ctrl + V hoặc chọn Dán.');els.input.focus();}});
