// Bảng giá theo cấu hình máy chủ (admin đổi trong /admin), không ghi cứng.
function renderPricing(data) {
  const price = Number(data?.price_per_million), fee = Number(data?.service_fee);
  if (Number.isFinite(price) && price > 0) {
    document.querySelector("#priceToken").textContent = `DeepSeek · ${money(price)} / 1.000.000 token`;
    document.querySelector("#deskPrice").textContent = `DeepSeek tính ${money(price)} cho 1 triệu token. NVIDIA, Gemini, Groq, Cloudflare miễn phí.`;
  }
  if (Number.isFinite(fee)) {
    document.querySelector("#priceService").textContent = fee === 0 ? "Phí duy trì · Miễn phí" : `Phí duy trì · ${money(fee)} / 30 ngày sau ${data.trial_days || 30} ngày dùng thử`;
    if (LIVE && session) document.querySelector("#walletTrial").textContent = fee === 0 ? "Miễn phí duy trì" : (data.wallet?.service_active === false ? "Hết hạn duy trì, cần gia hạn" : "Đang trong hạn duy trì");
  }
}

// Quên mật khẩu: gửi liên kết đặt lại qua email đã xác minh.
document.querySelector("#forgotLink").addEventListener("click", () => {
  closeOverlay("#authOverlay");
  document.querySelector("#resetError").hidden = true; document.querySelector("#resetDone").hidden = true;
  document.querySelector("#resetSubmit").disabled = false;
  openOverlay("#resetOverlay"); document.querySelector("#resetEmail").focus();
});
document.querySelector("#resetBack").addEventListener("click", () => { closeOverlay("#resetOverlay"); openOverlay("#authOverlay"); });
document.querySelector("#resetForm").addEventListener("submit", async (event) => {
  event.preventDefault();
  const err = document.querySelector("#resetError"), done = document.querySelector("#resetDone"), btn = document.querySelector("#resetSubmit");
  err.hidden = true; done.hidden = true;
  if (!LIVE) { done.textContent = "Bản demo không gửi email."; done.hidden = false; return; }
  btn.disabled = true;
  try {
    const data = await api("/api/email/password/request", { email: document.querySelector("#resetEmail").value.trim() });
    done.textContent = data.message || "Đã gửi liên kết. Kiểm tra hộp thư, cả thư rác."; done.hidden = false;
  } catch (e) { err.textContent = e.message; err.hidden = false; btn.disabled = false; }
});

// Thẻ số liệu trực tiếp (thời tiết, giá vàng, tin tức) kèm biểu đồ nhỏ, vẽ bằng SVG từ dữ liệu Worker đã tra.
let pendingLiveCard = null;
const WEATHER_TEXT = { 0: "Trời quang", 1: "Ít mây", 2: "Có mây", 3: "Nhiều mây", 45: "Sương mù", 48: "Sương mù", 51: "Mưa phùn", 53: "Mưa phùn", 55: "Mưa phùn", 61: "Mưa nhẹ", 63: "Mưa vừa", 65: "Mưa to", 80: "Mưa rào", 81: "Mưa rào", 82: "Mưa rào mạnh", 95: "Dông", 96: "Dông, mưa đá", 99: "Dông, mưa đá" };
function svgEl(tag, attrs) { const e = document.createElementNS("http://www.w3.org/2000/svg", tag); for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v); return e; }
function liveTime(iso) { const d = new Date(iso); return isNaN(d) ? "" : d.toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" }) + " " + d.toLocaleDateString("vi-VN"); }
function liveCardNode(card) {
  const box = document.createElement("section");
  box.className = "live-card live-" + card.kind;
  const head = document.createElement("header");
  const title = { weather: "Thời tiết" + (card.place ? " · " + card.place.split(",")[0] : ""), gold: "Giá vàng PNJ", news: "Tin mới VnExpress" }[card.kind] || "Dữ liệu trực tiếp";
  head.append(Object.assign(document.createElement("strong"), { textContent: title }), Object.assign(document.createElement("span"), { textContent: "Tra lúc " + liveTime(card.searched_at) }));
  box.append(head);
  if (card.kind === "weather" && card.current) {
    const now = document.createElement("div"); now.className = "live-now";
    now.append(Object.assign(document.createElement("b"), { textContent: Math.round(card.current.temperature) + "°C" }),
      Object.assign(document.createElement("span"), { textContent: [WEATHER_TEXT[card.current.code] || "", card.current.humidity != null ? "Ẩm " + card.current.humidity + "%" : "", card.current.wind != null ? "Gió " + Math.round(card.current.wind) + " km/h" : ""].filter(Boolean).join(" · ") }));
    box.append(now);
    const days = (card.daily || []).filter(d => Number.isFinite(d.max) && Number.isFinite(d.min));
    if (days.length) {
      const W = 320, H = 132, top = 18, bottom = 34, colW = W / days.length;
      const lo = Math.min(...days.map(d => d.min)) - 1, hi = Math.max(...days.map(d => d.max)) + 1;
      const y = v => top + (hi - v) / (hi - lo) * (H - top - bottom);
      const svg = svgEl("svg", { viewBox: `0 0 ${W} ${H}`, class: "live-chart", role: "img", "aria-label": "Nhiệt độ cao nhất, thấp nhất và khả năng mưa 7 ngày" });
      days.forEach((d, i) => {
        const cx = colW * i + colW / 2;
        if (Number.isFinite(d.rain)) svg.append(svgEl("rect", { x: cx - colW * 0.32, y: H - bottom - (d.rain / 100) * (H - top - bottom), width: colW * 0.64, height: (d.rain / 100) * (H - top - bottom), class: "rain" }));
        svg.append(svgEl("line", { x1: cx, x2: cx, y1: y(d.max), y2: y(d.min), class: "range" }));
        svg.append(svgEl("circle", { cx, cy: y(d.max), r: 3, class: "hi" }), svgEl("circle", { cx, cy: y(d.min), r: 3, class: "lo" }));
        const t1 = svgEl("text", { x: cx, y: y(d.max) - 6, class: "val" }); t1.textContent = Math.round(d.max) + "°";
        const t2 = svgEl("text", { x: cx, y: H - 18, class: "day" }); t2.textContent = i === 0 ? "Nay" : new Date(d.date).toLocaleDateString("vi-VN", { weekday: "short" });
        const t3 = svgEl("text", { x: cx, y: H - 5, class: "pop" }); t3.textContent = Number.isFinite(d.rain) ? d.rain + "%" : "";
        svg.append(t1, t2, t3);
      });
      box.append(svg);
      box.append(Object.assign(document.createElement("p"), { className: "live-legend", textContent: "Chấm: cao nhất / thấp nhất · Cột: khả năng mưa" }));
    }
  } else if (card.kind === "gold" && card.items?.length) {
    const num = v => Number(String(v).replace(/,/g, ""));
    const max = Math.max(...card.items.map(r => num(r.sell)));
    const list = document.createElement("div"); list.className = "live-bars";
    for (const r of card.items) {
      const row = document.createElement("div"); row.className = "live-bar";
      const bar = document.createElement("i"); bar.style.width = Math.max(8, num(r.sell) / max * 100) + "%";
      row.append(Object.assign(document.createElement("span"), { textContent: r.name }), bar,
        Object.assign(document.createElement("b"), { textContent: r.buy + " / " + r.sell }));
      list.append(row);
    }
    box.append(list, Object.assign(document.createElement("p"), { className: "live-legend", textContent: "Mua vào / bán ra, đơn vị " + (card.unit || "1.000 đồng/chỉ") + (card.updated_at ? " · Nguồn cập nhật " + card.updated_at : "") }));
  } else if (card.kind === "gold" && (card.sources || []).length) {
    const ul = document.createElement("ul"); ul.className = "live-news";
    for (const n of card.sources) { const li = document.createElement("li"); li.append(Object.assign(document.createElement("a"), { href: n.url, target: "_blank", rel: "noopener", textContent: n.title })); ul.append(li); }
    box.append(Object.assign(document.createElement("p"), { className: "live-legend", textContent: "Bảng giá PNJ tạm không đọc được. Số liệu lấy từ kết quả tìm kiếm:" }), ul);
    card = { ...card, sources: [] };
  } else if (card.kind === "news" && card.items?.length) {
    const ul = document.createElement("ul"); ul.className = "live-news";
    for (const n of card.items) {
      const a = Object.assign(document.createElement("a"), { href: n.url, target: "_blank", rel: "noopener", textContent: n.title });
      const li = document.createElement("li"); li.append(a); ul.append(li);
    }
    box.append(ul);
  }
  const src = (card.sources || [])[0];
  if (src) { const f = document.createElement("a"); f.className = "live-src"; f.href = src.url; f.target = "_blank"; f.rel = "noopener"; f.textContent = "Nguồn: " + src.title; box.append(f); }
  return box;
}

// Tạo ảnh / video từ mô tả tiếng Việt qua /api/media/* của Worker.
function selectedTool() { return document.querySelector('.composer-tools [data-tool][aria-pressed="true"]')?.dataset.tool || ""; }
function mediaMode(text) {
  const tool = selectedTool();
  if (tool === "Hình ảnh") return "image";
  if (tool === "Video") return "video";
  const f = text.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/đ/g, "d").toLowerCase();
  if (/^(hay |giup (toi|minh) )?(tao|lam|dung) (mot |1 )?(video|clip|doan phim)\b/.test(f)) return "video";
  if (chartRequest(text)) return null;
  if (/\b(tao|ve|thiet ke|lam|cho (toi|minh)|ra) (cho (toi|minh) )?(mot |1 |vai |cac )?(anh|hinh anh|hinh minh hoa|buc anh|buc tranh|tranh|poster|logo|banner|avatar|hinh nen|anh bia)\b/.test(f)) return "image";
  if (/^(hay |giup (toi|minh) )?ve (mot |1 )?(con|canh|chan dung|nguoi|ngoi nha|phong canh|cay|thanh pho|bien|nui)\b/.test(f)) return "image";
  return null;
}
function syncMediaOptions() {
  const tool = selectedTool(), box = document.querySelector("#mediaOptions");
  const doc = tool === "Tài liệu";
  box.hidden = tool !== "Hình ảnh" && tool !== "Video" && !doc;
  document.querySelector("#fileTypeWrap").hidden = !doc;
  const video = tool === "Video";
  document.querySelector("#videoSecondsWrap").hidden = !video;
  document.querySelector("#videoFrameWrap").hidden = !video;
  document.querySelector("#imageStyleWrap").hidden = video || doc;
  document.querySelector("#mediaHint").textContent = doc ? "Tạo file để tải về" : video ? "Tạo video từ mô tả tiếng Việt" : "Tạo ảnh từ mô tả tiếng Việt";
  if (doc) { els.input.placeholder = "Mô tả nội dung file, ví dụ: bảng chỉ tiêu cơ lý 3 lớp đất"; return; }
  if (!box.hidden) els.input.placeholder = video ? "Mô tả cảnh quay, ví dụ: flycam cánh đồng lúa Tam Cốc lúc bình minh" : "Mô tả ảnh, ví dụ: kỹ sư khảo sát đê sông Hồng lúc hoàng hôn";
  else els.input.placeholder = "Hỏi bất cứ điều gì…";
}
document.querySelectorAll(".composer-tools [data-tool]").forEach((b) => b.addEventListener("click", () => setTimeout(syncMediaOptions)));
function mediaCard(kind) {
  const row = addMessage("assistant", "");
  row.p.remove();
  const box = Object.assign(document.createElement("section"), { className: "media-card" });
  const state = Object.assign(document.createElement("p"), { className: "media-state", textContent: kind === "video" ? "Đang gửi yêu cầu tạo video…" : "Đang tạo ảnh…" });
  const bar = Object.assign(document.createElement("div"), { className: "media-progress" }); bar.append(document.createElement("i"));
  box.append(state, bar); row.body.prepend(box); scrollThread();
  return { box, state, bar };
}
async function runMedia(kind, text) {
  if (!LIVE) { toast("Bản demo chưa nối máy chủ tạo ảnh/video."); return; }
  if (!session) { requireAccount("Đăng nhập để tạo ảnh hoặc video."); return; }
  addMessage("user", text);
  const ui = mediaCard(kind);
  setGenerating(true);
  try {
    if (kind === "image") {
      const data = await api("/api/media/image", { ...credentials(), prompt: text, style: document.querySelector("#imageStyle").value });
      const src = "data:" + (data.mime || "image/jpeg") + ";base64," + data.image;
      const img = Object.assign(document.createElement("img"), { src, alt: text.slice(0, 120), className: "media-image" });
      const save = Object.assign(document.createElement("a"), { href: src, download: "ChatAI-anh.jpg", className: "media-save", textContent: "Tải ảnh" });
      ui.box.replaceChildren(img, save);
    } else {
      const created = await api("/api/media/video/create", { ...credentials(), prompt: text, request_id: crypto.randomUUID(),
        seconds: Number(document.querySelector("#videoSeconds").value), frame: document.querySelector("#videoFrame").value });
      ui.state.textContent = `Đang dựng video ${created.seconds || ""} giây… Thường mất 1–5 phút, bạn có thể tiếp tục chat.`;
      setGenerating(false);
      const started = Date.now();
      while (Date.now() - started < 20 * 60000) {
        await new Promise((r) => setTimeout(r, 6000));
        const st = await api("/api/media/video/status", { ...credentials(), id: created.id });
        ui.bar.firstChild.style.width = Math.max(5, st.progress || 0) + "%";
        if (st.status === "failed") throw new Error("Dịch vụ video báo tạo thất bại. Thử mô tả khác.");
        if (st.status === "completed") {
          const res = await fetch("/api/media/video/content", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...credentials(), id: created.id }) });
          if (!res.ok) throw new Error("Không tải được video đã tạo.");
          const url = URL.createObjectURL(await res.blob());
          const video = Object.assign(document.createElement("video"), { src: url, controls: true, playsInline: true, className: "media-video" });
          const save = Object.assign(document.createElement("a"), { href: url, download: "ChatAI-video.mp4", className: "media-save", textContent: "Tải video" });
          ui.box.replaceChildren(video, save); scrollThread();
          return;
        }
      }
      throw new Error("Video chưa xong sau 20 phút. Kiểm tra lại sau.");
    }
  } catch (e) {
    ui.box.replaceChildren(Object.assign(document.createElement("p"), { className: "media-state is-error", textContent: e.message }));
  } finally { setGenerating(false); scrollThread(); }
}

// Tệp đính kèm: ảnh, Excel, Word, PDF, DXF và văn bản/code. Đọc ngay trên trình duyệt; thư viện chỉ tải khi cần.
let turnAttachment = null;
const DOC_LIMIT = 120000;
function deepOn() { return document.querySelector('.composer-tools [data-tool="Phân tích sâu"]')?.getAttribute("aria-pressed") === "true"; }
function turnPayload() {
  const a = turnAttachment; turnAttachment = null;
  if (!a) return {};
  return a.image ? { image: a.image } : { document_context: "Tệp " + a.name + ":\n" + a.text.slice(0, DOC_LIMIT) };
}
function loadScript(src) {
  return new Promise((ok, bad) => { if (document.querySelector(`script[src="${src}"]`)) return ok(); const s = Object.assign(document.createElement("script"), { src, onload: ok, onerror: () => bad(new Error("Không tải được thư viện đọc tệp.")) }); document.head.append(s); });
}
async function readImage(file) {
  const bmp = await createImageBitmap(file);
  const scale = Math.min(1, 1280 / Math.max(bmp.width, bmp.height));
  const c = Object.assign(document.createElement("canvas"), { width: Math.round(bmp.width * scale), height: Math.round(bmp.height * scale) });
  c.getContext("2d").drawImage(bmp, 0, 0, c.width, c.height);
  let q = 0.85, data = "";
  do { data = c.toDataURL("image/jpeg", q).split(",")[1]; q -= 0.15; } while (data.length > 1300000 && q > 0.2);
  if (data.length > 1390000) throw new Error("Ảnh quá lớn sau khi nén. Chọn ảnh nhỏ hơn.");
  return { mime: "image/jpeg", data };
}
async function readXlsx(file) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js");
  const wb = XLSX.read(await file.arrayBuffer(), { type: "array" });
  return wb.SheetNames.map((n) => "### Sheet: " + n + "\n" + XLSX.utils.sheet_to_csv(wb.Sheets[n], { blankrows: false })).join("\n\n");
}
async function readDocx(file) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js");
  return (await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() })).value;
}
async function readPdf(file) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js");
  pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
  const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
  const out = [];
  for (let i = 1; i <= pdf.numPages && out.join("").length < DOC_LIMIT; i++) {
    const page = await pdf.getPage(i);
    out.push("--- Trang " + i + " ---\n" + (await page.getTextContent()).items.map((it) => it.str).join(" "));
  }
  const text = out.join("\n");
  if (text.replace(/[-\s\dTrang]/g, "").length < 20) throw new Error("PDF này là ảnh quét, chưa có chữ để đọc. Chụp trang và đính kèm dạng ảnh.");
  return text;
}
// DXF (ASCII): lớp, số lượng đối tượng, khung bao toạ độ và toàn bộ chữ TEXT/MTEXT.
function readDxfText(raw) {
  const lines = raw.split(/\r?\n/);
  const counts = {}, layers = new Set(), texts = [];
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity, entity = "", inEntities = false;
  for (let i = 0; i + 1 < lines.length; i += 2) {
    const code = lines[i].trim(), val = lines[i + 1].trim();
    if (code === "2" && (val === "ENTITIES")) inEntities = true;
    if (code === "0") { if (val === "ENDSEC") inEntities = false; entity = val; if (inEntities && val !== "SEQEND" && val !== "VERTEX") counts[val] = (counts[val] || 0) + 1; }
    if (!inEntities) continue;
    if (code === "8") layers.add(val);
    if ((code === "1" || code === "3") && (entity === "TEXT" || entity === "MTEXT" || entity === "ATTRIB")) texts.push(val.replace(/\\P/g, " ").replace(/\{\\[^;]*;|\}/g, ""));
    const n = Number(val);
    if (Number.isFinite(n) && (code === "10" || code === "11")) { minX = Math.min(minX, n); maxX = Math.max(maxX, n); }
    if (Number.isFinite(n) && (code === "20" || code === "21")) { minY = Math.min(minY, n); maxY = Math.max(maxY, n); }
  }
  if (!Object.keys(counts).length) throw new Error("Không đọc được DXF. Lưu bản vẽ dạng DXF ASCII rồi thử lại.");
  return ["Bản vẽ DXF", "Đối tượng: " + Object.entries(counts).map(([k, v]) => k + " " + v).join(", "),
    "Lớp (" + layers.size + "): " + [...layers].join(", "),
    Number.isFinite(minX) ? `Khung bao: X ${minX.toFixed(2)} → ${maxX.toFixed(2)}, Y ${minY.toFixed(2)} → ${maxY.toFixed(2)}` : "",
    "Chữ trong bản vẽ (" + texts.length + "):", ...texts].join("\n");
}
async function readAttachment(file) {
  if (!file) return;
  const chip = document.querySelector("#attachmentChip"), name = file.name, ext = (name.split(".").pop() || "").toLowerCase();
  if (file.size > 25 * 1024 * 1024) { toast("Tệp lớn hơn 25 MB."); clearAttachment(); return; }
  chip.querySelector("span").textContent = "Đang đọc " + name + "…"; chip.hidden = false;
  try {
    if (file.type.startsWith("image/")) {
      attachment = { name, image: await readImage(file) };
      chip.querySelector("span").textContent = "🖼 " + name;
    } else {
      let text;
      if (["xlsx", "xls"].includes(ext)) text = await readXlsx(file);
      else if (ext === "docx") text = await readDocx(file);
      else if (ext === "pdf") text = await readPdf(file);
      else if (ext === "dxf") text = readDxfText(await file.text());
      else { text = await file.text(); if (text.includes("\u0000")) throw new Error("Định dạng này chưa đọc được trên web."); }
      if (!text.trim()) throw new Error("Tệp không có nội dung chữ.");
      const cut = text.length > DOC_LIMIT;
      attachment = { name, text: text.slice(0, DOC_LIMIT) };
      chip.querySelector("span").textContent = "↳ " + name + " · " + Math.min(text.length, DOC_LIMIT).toLocaleString("vi-VN") + " ký tự" + (cut ? " (đã cắt bớt)" : "");
    }
    els.input.focus();
  } catch (e) { toast(e.message || "Không đọc được tệp."); clearAttachment(); }
  document.querySelector("#fileInput").value = "";
}

// Tạo file tải về: AI trả khối ```chatai-file {JSON}```, trình duyệt dựng Word / Excel / PowerPoint / PDF / DXF.
const FILE_LIBS = {
  xlsx: "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js",
  docx: "https://cdn.jsdelivr.net/npm/docx@8.5.0/build/index.umd.js",
  pptx: "https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/dist/pptxgen.bundle.js",
  pdf: ["https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.2.7/pdfmake.min.js", "https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.2.7/vfs_fonts.js"],
};
const FILE_NAMES = { docx: "Word", xlsx: "Excel", pptx: "PowerPoint", pdf: "PDF", dxf: "DXF" };
function fileRequest(text) {
  if (selectedTool() === "Tài liệu") return document.querySelector("#fileType").value;
  const f = text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").toLowerCase();
  if (!/\b(tao|lam|xuat|soan|viet|ve|lap|chuyen)\b/.test(f) || !/\b(file|tep|ban|tai lieu|ra|sang|thanh|slide|bang tinh|ban ve)\b/.test(f)) return null;
  if (/\b(dxf|autocad|cad|ban ve)\b/.test(f)) return "dxf";
  if (/\b(powerpoint|pptx|ppt|slide|trinh chieu|thuyet trinh)\b/.test(f)) return "pptx";
  if (/\b(excel|xlsx|bang tinh)\b/.test(f)) return "xlsx";
  if (/\b(word|docx)\b/.test(f)) return "docx";
  if (/\bpdf\b/.test(f)) return "pdf";
  return null;
}
function FILE_INSTRUCTION(kind) {
  const shape = {
    xlsx: '{"type":"xlsx","filename":"ten-file","sheets":[{"name":"Sheet1","rows":[["Cột A","Cột B"],["giá trị",123]]}]}',
    docx: '{"type":"docx","filename":"ten-file","title":"Tiêu đề","sections":[{"heading":"Mục 1","paragraphs":["..."],"bullets":["..."],"table":[["Cột","Cột"],["...","..."]]}]}',
    pdf: '{"type":"pdf","filename":"ten-file","title":"Tiêu đề","sections":[{"heading":"Mục 1","paragraphs":["..."],"bullets":["..."],"table":[["Cột","Cột"],["...","..."]]}]}',
    pptx: '{"type":"pptx","filename":"ten-file","title":"Tiêu đề bài","slides":[{"title":"Slide 1","bullets":["ý 1","ý 2"],"notes":"ghi chú người nói"}]}',
    dxf: '{"type":"dxf","filename":"ten-file","units":"m","entities":[{"type":"line","layer":"MAT_CAT","x1":0,"y1":0,"x2":10,"y2":5},{"type":"polyline","layer":"DAT","points":[[0,0],[5,2],[10,2]],"closed":false},{"type":"circle","layer":"COC","x":3,"y":1,"r":0.4},{"type":"text","layer":"GHI_CHU","x":1,"y":6,"height":0.5,"text":"Ghi chú"}]}',
  }[kind];
  return `[Yêu cầu tạo file ${FILE_NAMES[kind]}] Trả lời ngắn gọn nội dung chính, sau đó đặt ĐÚNG MỘT khối ở cuối câu trả lời theo mẫu:\n\`\`\`chatai-file\n${shape}\n\`\`\`\nJSON hợp lệ, đầy đủ nội dung thật (không dùng "..."), số để dạng số, tiếng Việt có dấu.`;
}
function extractFileSpec(text) {
  const m = String(text || "").match(/```chatai-file\s*([\s\S]*?)```/);
  if (!m) return { clean: text, spec: null };
  let spec = null;
  try { spec = JSON.parse(m[1]); } catch { try { spec = JSON.parse(m[1].replace(/,\s*([}\]])/g, "$1")); } catch {} }
  const clean = String(text).replace(m[0], "").trim();
  return { clean, spec: spec && FILE_NAMES[spec.type] ? spec : { error: true } };
}
// DXF R12 ASCII: LINE, CIRCLE, TEXT; polyline ghi thành các LINE để mọi phần mềm CAD đọc được. Chữ có dấu ghi dạng \U+XXXX.
