    svg.append(el("text", { x: L + 18 + si * 130, y: H - 12, "font-size": 11, fill: "#0f1a2b" }, (sr.name || "Dãy " + (si + 1)) + (spec.unit && si === 0 ? ` (${spec.unit})` : "")));
